import {deriveFighterStats} from './fighter-attributes.mjs?v=chapter-presentation-20261117-r1';
// Pure presentation over the same calculator used by combat, never a rating.
export const ABILITY_BRANCHES=Object.freeze([
 ['hp','續航氣勢','氣勢','maxHp','氣勢上限 +3%'],
 ['move','靈活走位','走速','moveMultiplier','走速 +1%'],
 ['basic','基本功','普攻','basicMultiplier','普攻與投擲道具傷害 +2%'],
 ['defense','防守韌性','耐傷','damageTakenMultiplier','承受傷害 −1.5%'],
 ['special','招牌絕招','絕招傷害倍率','specialMultiplier','絕招傷害倍率 +2%'],
 ['rally','揪團聲勢','揪團傷害倍率','rallyMultiplier','揪團傷害倍率 +2%'],
 ['assist','助拳默契','助拳傷害倍率','assistMultiplier','助拳傷害倍率 +2%'],
]);
export const escapeAbility=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeAbility;
const decimal=v=>Number(v.toFixed(3)).toString();
const statLabels={maxHp:'氣勢上限',moveMultiplier:'走速倍率',basicMultiplier:'普攻傷害倍率',damageTakenMultiplier:'承傷倍率（越低越耐傷）',specialMultiplier:'絕招傷害倍率',rallyMultiplier:'揪團傷害倍率',assistMultiplier:'助拳傷害倍率'};
const value=(key,v)=>key==='maxHp'?decimal(v):'×'+decimal(v);
export function radarValues(stats){return [stats.maxHp,stats.moveMultiplier*100,stats.basicMultiplier*100,100/stats.damageTakenMultiplier,stats.specialMultiplier*100,stats.rallyMultiplier*100,stats.assistMultiplier*100];}
export function abilityRadarMarkup(id,{savedSkills={},draftSkills=null}={}){
 const base=deriveFighterStats(id),saved=deriveFighterStats(id,{skills:savedSkills,challenge:true}),draft=draftSkills&&deriveFighterStats(id,{skills:draftSkills,challenge:true});
 const point=(i,r)=>{const a=-Math.PI/2+i*2*Math.PI/7;return [160+Math.cos(a)*r,150+Math.sin(a)*r].map(n=>n.toFixed(2)).join(',');};
 const shape=(name,stats)=>{const values=radarValues(stats);return `<polygon data-radar="${name}" data-values="${esc(JSON.stringify(values))}" class="radar-${name}" points="${values.map((v,i)=>point(i,98*Math.max(0,Math.min(140,v))/140)).join(' ')}"/>`;};
 return `<svg class="challenge-radar ability-radar" data-scale="0-140" viewBox="0 0 320 300" role="img" aria-label="七項實際能力；共同刻度零至一百四十，天生、已保存${draft?'及草稿':''}"><title>固定 0–140 能力指數，不是綜合戰力</title>${[35,70,100,140].map(n=>`<polygon class="radar-grid" points="${ABILITY_BRANCHES.map((_,i)=>point(i,98*n/140)).join(' ')}"/>`).join('')}${ABILITY_BRANCHES.map((_,i)=>`<line class="radar-grid" x1="160" y1="150" x2="${point(i,98).replace(',','" y2="')}"/>`).join('')}${shape('base',base)}${shape('saved',saved)}${draft?shape('draft',draft):''}${ABILITY_BRANCHES.map(([k,,label],i)=>{const [x,y]=point(i,128).split(',');return `<text data-axis="${k}" x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle">${label}</text>`;}).join('')}<text class="radar-scale" x="165" y="55">140</text><text class="radar-scale" x="165" y="84">100</text><text class="radar-scale" x="165" y="150">0</text></svg><p class="ability-legend"><span class="legend-base">淡線：天生</span><span class="legend-saved">實線：已保存</span>${draft?'<span class="legend-draft">虛線：草稿</span>':''}</p><p class="ability-radar-note">共同刻度 0–140。耐傷 = 100／承傷倍率；走速及傷害倍率 ×100。不是綜合戰力，後三軸相同不代表招式一樣強。</p>`;
}
export function moveDamageParts(move){
 if(['heal','reject','calm','armor','brace'].includes(move.behavior))return [];
 if(move.hits?.length)return move.hits.filter(hit=>Number.isFinite(hit.damage)).map((hit,i)=>({label:`第 ${i+1} 擊`,value:hit.damage}));
 const parts=[];if(Number.isFinite(move.damage))parts.push({label:move.returnDamage?'去程':move.airDamage?'地面':'命中',value:move.damage});
 for(const [key,label]of [['returnDamage','回程'],['airDamage','對空'],['wallBonus','撞牆另加（最多）']])if(Number.isFinite(move[key]))parts.push({label,value:move[key],...(key==='wallBonus'?{unscaled:true}:{})});return parts;
}
export function characterAbilityMarkup({id,character={},savedSkills={},draftSkills=null,allowance=0,readOnly=false,locked=false}={}){
 const editable=!readOnly,stats=deriveFighterStats(id,{skills:draftSkills||savedSkills,challenge:true}),ranks=stats.skills,remaining=Math.max(0,allowance-stats.spent);
 const skillCards=ABILITY_BRANCHES.map(([k,label,,stat,effect])=>{const rank=ranks[k],next=deriveFighterStats(id,{skills:{...ranks,[k]:Math.min(5,rank+1)},challenge:true});const reason=readOnly?'戰鬥中唯讀':locked?'保存處理中':rank>=5?'已達本支上限':remaining===0?'額度已用完，可先減少其他分支':'可增加 1 點';return `<article class="challenge-node ${rank?'has-ranks':''}" data-skill-card="${k}"><span><strong>${label}</strong><small>每點 ${effect}</small></span><span class="challenge-ranks" aria-label="已投入 ${rank}，上限 5">${Array.from({length:5},(_,i)=>`<i class="${i<rank?'filled':''}"></i>`).join('')}</span><b>${rank} / 5</b><p class="ability-next">${rank===5?'已達上限':`下一點：${value(stat,stats[stat])} → ${value(stat,next[stat])}`}</p>${editable?`<div class="ability-rank-actions"><button type="button" data-skill="${k}" data-delta="-1" aria-label="減少${label}" ${locked||rank===0?'disabled':''}>−</button><span>${reason}</span><button type="button" data-skill="${k}" data-delta="1" aria-label="增加${label}" ${locked||rank>=5||remaining===0?'disabled':''}>＋</button></div>`:'<span class="ability-readonly">唯讀 · 已保存配點</span>'}</article>`;}).join('');
 return `<div class="challenge-bio"><div class="ability-portrait">${character.portrait?`<img src="${esc(character.portrait)}" alt="${esc(character.name||id)}"/>`:''}</div><div><span class="challenge-tag">${esc(character.tag||'街頭選手')}</span><h3>${esc(character.name||id)}</h3><p>${esc(character.roast||'')}</p><p>${esc(character.tip||'')}</p></div></div><div class="challenge-build ability-build"><section class="challenge-chart">${abilityRadarMarkup(id,{savedSkills,draftSkills:editable?draftSkills:null})}<h4>基本 → 加點 → 結果${editable?'（草稿）':''}</h4><dl class="challenge-stats ability-stats">${ABILITY_BRANCHES.map(([,label,,stat])=>`<div data-stat="${stat}"><dt>${statLabels[stat]}</dt><dd>${value(stat,stats.base[stat])} → ${stats.bonus[stat]>=0?'+':''}${decimal(stats.bonus[stat])} → <strong>${value(stat,stats[stat])}</strong></dd></div>`).join('')}</dl><p>基本能力各模式相同；加點只作用於挑戰。防守仍為 3 格。</p></section><section class="challenge-tree"><h4>自由技能樹 <span>剩餘 ${remaining} / ${allowance} 點</span></h4><p class="challenge-fine">每位角色有同額獨立額度，七支無前置限制，不解鎖新招。每 80 隊伍 XP 增加 1 點，總額上限 35。</p><div class="challenge-tree-root"><span aria-hidden="true">★</span> ${esc(character.name||id)} · 自由養成</div><div class="challenge-branches">${skillCards}</div>${editable?`<button type="button" id="preparationReset" data-reset-skills ${locked||stats.spent===0?'disabled':''}>重置此角色草稿配點</button><p class="challenge-fine">僅退回這個角色的草稿配點，確認保存前不改原檔。</p>`:''}</section></div><section class="challenge-moves ability-moves"><h4>現有招牌招式 · ${(character.moves||[]).length} 招</h4><p class="challenge-fine">列出實際招式基礎傷害 → 目前加點傷害；未計對手承傷、防守或場景修正。回復與控制不算傷害。</p><div class="ability-move-grid">${(character.moves||[]).map(move=>{const parts=moveDamageParts(move);return `<article data-move-kind="${esc(move.kind)}"><h5>${esc(move.name)}</h5><p>${esc(move.hint||move.purpose)}</p><p class="ability-damage">${parts.length?parts.map(part=>`${part.label} ${decimal(part.value)} → ${decimal(part.unscaled?part.value:part.value*stats.specialMultiplier)}`).join('；'):move.behavior==='heal'?`回復 ${decimal(move.heal||0)} 氣勢（不受傷害加點影響）`:'防守／控制效果；無直接傷害'}</p><p>冷卻 ${decimal(move.cooldown||0)} 秒</p></article>`;}).join('')}</div></section>`;
}
